export const CustomerSalePaymentListSchema = {
    type: 'object',
    description: 'Read-only serializer for listing a customer\'s payments across every sale.\n\nDenormalizes the sale it belongs to, because the nested per-sale payment\nendpoint never exposed it and the client has no other way to tell which sale\na payment affected.',
    properties: {
        id: {
            type: 'string',
            format: 'uuid',
            readOnly: true
        },
        sale: {
            type: 'string',
            format: 'uuid',
            readOnly: true
        },
        sale_seq_number: {
            type: 'integer',
            readOnly: true
        },
        customer: {
            type: 'string',
            readOnly: true
        },
        payment_date: {
            type: 'string',
            format: 'date-time',
            readOnly: true
        },
        currency: {
            type: 'string',
            readOnly: true
        },
        payment_method: {
            type: 'string',
            readOnly: true
        },
        REF: {
            type: 'string',
            readOnly: true,
            nullable: true
        },
        discount: {
            type: 'string',
            format: 'decimal',
            pattern: '^-?\\d{0,8}(?:\\.\\d{0,2})?$',
            readOnly: true
        },
        total_amount_usd: {
            type: 'string',
            format: 'decimal',
            pattern: '^-?\\d{0,10}(?:\\.\\d{0,2})?$',
            readOnly: true
        },
        total_amount_ves: {
            type: 'string',
            format: 'decimal',
            pattern: '^-?\\d{0,10}(?:\\.\\d{0,2})?$',
            readOnly: true
        },
        exchange_rate: {
            type: 'string',
            format: 'uuid',
            readOnly: true,
            nullable: true
        },
        reverses: {
            type: 'string',
            format: 'uuid',
            readOnly: true,
            nullable: true
        },
        reversal_reason: {
            type: 'string',
            readOnly: true,
            nullable: true
        },
        is_reversed: {
            type: 'boolean',
            readOnly: true
        },
        created_at: {
            type: 'string',
            format: 'date-time',
            readOnly: true
        }
    },
    required: [
        'REF',
        'created_at',
        'currency',
        'customer',
        'discount',
        'exchange_rate',
        'id',
        'is_reversed',
        'payment_date',
        'payment_method',
        'reversal_reason',
        'reverses',
        'sale',
        'sale_seq_number',
        'total_amount_usd',
        'total_amount_ves'
    ]
} as const;

